using SharpTS.Tests.Infrastructure;
using Xunit;

namespace SharpTS.Tests.CompilerTests;

[Collection("CompilationService")]
public sealed class TypedArrayCompoundKeyConversionTests
{
    public static IEnumerable<object[]> Cases()
    {
        yield return ["original", "let calls=0;const p=new Uint8Array([1,9]),key:any={[Symbol.toPrimitive](hint:string){console.log(hint);return ++calls===1?'0':'1'}};const result=p[key]+=7;console.log(p[0],p[1],result,calls);", "string\nstring\n1 8 8 2\n"];
        yield return ["erased-number-assertion", "const log:string[]=[];let calls=0;const key:any={[Symbol.toPrimitive](hint:string){log.push(hint);return ++calls===1?'0':'1'}};const p=new Uint8Array([1,9]);const result=p[key as number]+=7;console.log(p[0],p[1],result,calls,log.join(','));", "1 8 8 2 string,string\n"];
        yield return ["numeric-coercion-result", "const log:string[]=[];let calls=0;const key:any={[Symbol.toPrimitive](hint:string){log.push(hint);return ++calls===1?0:1}};const p=new Uint8Array([1,9]);const result=p[key]+=7;console.log(p[0],p[1],result,calls,log.join(','));", "1 8 8 2 string,string\n"];
        yield return ["key-expression-once", "const log:string[]=[];let calls=0;const key:any={[Symbol.toPrimitive](hint:string){log.push(hint);return ++calls===1?'0':'1'}};let keys=0;function getKey(){keys++;return key}const p=new Uint8Array([1,9]);const result=p[getKey()]+=7;console.log(p[0],p[1],result,calls,keys,log.join(','));", "1 8 8 2 1 string,string\n"];
        yield return ["rhs-changes-key", "const log:string[]=[];let fieldName='0';const key:any={[Symbol.toPrimitive](hint:string){log.push(hint+fieldName);return fieldName}};const p=new Uint8Array([1,9]);function rhs(){log.push('rhs');fieldName='1';return 7}const result=p[key]+=rhs();console.log(p[0],p[1],result,log.join(','));", "1 8 8 string0,rhs,string1\n"];
        yield return ["to-string-before-value-of", "const log:string[]=[];const key:any={toString(){log.push('string');return '0'},valueOf(){log.push('number');return 1}};const p=new Uint8Array([1,9]);const result=p[key]+=7;console.log(p[0],p[1],result,log.join(','));", "8 9 8 string,string\n"];
        yield return ["second-key-abrupt", "const marker={},log:string[]=[];let calls=0;const key:any={[Symbol.toPrimitive](hint:string){log.push(hint);if(++calls===2)throw marker;return '0'}};const p=new Uint8Array([1,9]);function rhs(){log.push('rhs');return 7}try{p[key]+=rhs()}catch(e){console.log(e===marker,p[0],p[1],log.join(','))}", "true 1 9 string,rhs,string\n"];
        yield return ["first-key-abrupt", "const marker={},log:string[]=[];const key:any={[Symbol.toPrimitive](hint:string){log.push(hint);throw marker}};const p=new Uint8Array([1,9]);function rhs(){log.push('rhs');return 7}try{p[key]+=rhs()}catch(e){console.log(e===marker,p[0],log.join(','))}", "true 1 string\n"];
        yield return ["rhs-abrupt", "const marker={},log:string[]=[];const key:any={[Symbol.toPrimitive](hint:string){log.push(hint);return '0'}};const p=new Uint8Array([1,9]);function rhs():number{log.push('rhs');throw marker}try{p[key]+=rhs()}catch(e){console.log(e===marker,p[0],log.join(','))}", "true 1 string,rhs\n"];
        yield return ["all-fast-operators", "{const p=new Uint8Array([8,99]),log:string[]=[];let n=0;const key:any={[Symbol.toPrimitive](hint:string){log.push(hint);return ++n===1?'0':'1'}};const result=p[key]+=2;console.log(p[0],p[1],result,n,log.join(','));}\n{const p=new Uint8Array([8,99]),log:string[]=[];let n=0;const key:any={[Symbol.toPrimitive](hint:string){log.push(hint);return ++n===1?'0':'1'}};const result=p[key]-=2;console.log(p[0],p[1],result,n,log.join(','));}\n{const p=new Uint8Array([8,99]),log:string[]=[];let n=0;const key:any={[Symbol.toPrimitive](hint:string){log.push(hint);return ++n===1?'0':'1'}};const result=p[key]*=2;console.log(p[0],p[1],result,n,log.join(','));}\n{const p=new Uint8Array([8,99]),log:string[]=[];let n=0;const key:any={[Symbol.toPrimitive](hint:string){log.push(hint);return ++n===1?'0':'1'}};const result=p[key]/=2;console.log(p[0],p[1],result,n,log.join(','));}\n{const p=new Uint8Array([8,99]),log:string[]=[];let n=0;const key:any={[Symbol.toPrimitive](hint:string){log.push(hint);return ++n===1?'0':'1'}};const result=p[key]%=2;console.log(p[0],p[1],result,n,log.join(','));}\n{const p=new Uint8Array([8,99]),log:string[]=[];let n=0;const key:any={[Symbol.toPrimitive](hint:string){log.push(hint);return ++n===1?'0':'1'}};const result=p[key]&=2;console.log(p[0],p[1],result,n,log.join(','));}\n{const p=new Uint8Array([8,99]),log:string[]=[];let n=0;const key:any={[Symbol.toPrimitive](hint:string){log.push(hint);return ++n===1?'0':'1'}};const result=p[key]|=2;console.log(p[0],p[1],result,n,log.join(','));}\n{const p=new Uint8Array([8,99]),log:string[]=[];let n=0;const key:any={[Symbol.toPrimitive](hint:string){log.push(hint);return ++n===1?'0':'1'}};const result=p[key]^=2;console.log(p[0],p[1],result,n,log.join(','));}\n{const p=new Uint8Array([8,99]),log:string[]=[];let n=0;const key:any={[Symbol.toPrimitive](hint:string){log.push(hint);return ++n===1?'0':'1'}};const result=p[key]<<=2;console.log(p[0],p[1],result,n,log.join(','));}\n{const p=new Uint8Array([8,99]),log:string[]=[];let n=0;const key:any={[Symbol.toPrimitive](hint:string){log.push(hint);return ++n===1?'0':'1'}};const result=p[key]>>=2;console.log(p[0],p[1],result,n,log.join(','));}", "8 10 10 2 string,string\n8 6 6 2 string,string\n8 16 16 2 string,string\n8 4 4 2 string,string\n8 0 0 2 string,string\n8 0 0 2 string,string\n8 10 10 2 string,string\n8 10 10 2 string,string\n8 32 32 2 string,string\n8 2 2 2 string,string\n"];
        yield return ["numeric-literal-control", "const p=new Uint8Array([1,2]);const a=p[0]+=7;const b=p[1]*=3;console.log(p[0],p[1],a,b);", "8 6 8 6\n"];
        yield return ["numeric-local-control", "const p=new Uint8Array([1,2]);let index:number=0;const a=p[index]+=7;index=1;const b=p[index]*=3;console.log(p[0],p[1],a,b);", "8 6 8 6\n"];
        yield return ["numeric-parameter-control", "function run(index:number){const p=new Uint8Array([1,2]);const result=p[index]+=7;console.log(p[0],p[1],result)}run(1);", "1 9 9\n"];
        yield return ["integer-loop-control", "const p=new Uint8Array([1,2]);let sum=0;for(let i=0;i<2;i++){sum+=(p[i]+=7)}console.log(p[0],p[1],sum);", "8 9 17\n"];
        yield return ["numeric-expression-control", "const p=new Uint8Array([1,2]);let sum=0;for(let i=0;i<2;i++){sum+=(p[(i+1)%2]+=7)}console.log(p[0],p[1],sum);", "8 9 17\n"];
        yield return ["numeric-assertion-control", "const p=new Uint8Array([1,2]);const index:number=1;const result=p[((index as number)!)]+=7;console.log(p[0],p[1],result);", "1 9 9\n"];
        yield return ["state-machine-control", "async function run(){let calls=0;const key:any={[Symbol.toPrimitive](hint:string){console.log(hint);return ++calls===1?'0':'1'}};const p=new Uint8Array([1,9]);const result=p[key]+=await Promise.resolve(7);console.log(p[0],p[1],result,calls)}run();", "string\nstring\n1 8 8 2\n"];
        yield return ["captured-parameter-key", "function run(index:number){const log:string[]=[];let calls=0;const key:any={[Symbol.toPrimitive](hint:string){log.push(hint);return ++calls===1?'0':'1'}};const write=()=>{index=key};write();const p=new Uint8Array([1,9]);const result=p[index]+=7;console.log(p[0],p[1],result,calls,log.join(','))}run(0);", "1 8 8 2 string,string\n"];
        yield return ["captured-local-key", "function run(){const log:string[]=[];let calls=0;const key:any={[Symbol.toPrimitive](hint:string){log.push(hint);return ++calls===1?'0':'1'}};let index:number=0;const write=()=>{index=key};write();const p=new Uint8Array([1,9]);const result=p[index]+=7;console.log(p[0],p[1],result,calls,log.join(','))}run();", "1 8 8 2 string,string\n"];
        yield return ["sibling-block-cell-key", "function run(){{let index:number=0;let calls=0;const key:any={[Symbol.toPrimitive](hint:string){console.log(hint);return ++calls===1?'0':'1'}};const write=()=>{index=key};write();const p=new Uint8Array([1,9]);console.log(p[index]+=7,p[0],p[1],calls)}{let index:number=0;const read=()=>index;index=1;const p=new Uint8Array([1,9]);console.log(p[index]+=7,p[0],p[1],read())}}run();", "string\nstring\n8 1 8 2\n16 1 16 1\n"];
    }

    [Theory, MemberData(nameof(Cases))]
    public void ObjectIndicesUseIndependentStringHintConversions(string name, string source, string expected)
    {
        Assert.NotEmpty(name);
        var (errors, output) = TestHarness.CompileVerifyAndRun(source);
        Assert.Empty(errors);
        Assert.Equal(expected, output);
    }
}
